/** Click-to-source and the provisional typing overlay for one compiled preview (both panes of the exercise editor, the Exam step's preview; issue #347). Owns the last result per pane, the overlays and the template tooltip. */
import {
  insertedText,
  isClickable,
  placeOfLine,
  rangeOf,
  resolveClick,
  wordAt,
  type ClickTarget,
  type PageClick,
  type PageOverlay,
  type SyncedResult,
} from './clickToSource';

export class PreviewSync {
  overlays = $state.raw<Record<string, PageOverlay | null>>({});
  /** Where the "generated by the template" tooltip shows, or null. */
  tip = $state.raw<{ x: number; y: number } | null>(null);
  private results = new Map<string, SyncedResult>();
  /** Bumped by every new result and `reset()`: a click resolved against an older one is dropped. */
  private seq = 0;

  /** A new PDF in `paneId` (or none): its overlay goes, the next click resolves against it. */
  setResult(paneId: string, result: SyncedResult | undefined): void {
    this.seq++;
    if (result) this.results.set(paneId, result);
    else this.results.delete(paneId);
    if (this.overlays[paneId]) this.overlays = { ...this.overlays, [paneId]: null };
  }

  /** A failed compile: the provisional text would never be replaced. */
  clearOverlays(): void {
    if (Object.values(this.overlays).some(Boolean)) this.overlays = {};
  }

  reset(): void {
    this.seq++;
    this.results.clear();
    this.overlays = {};
    this.tip = null;
  }

  clickable(paneId: string): boolean {
    return isClickable(this.results.get(paneId));
  }

  /** The source under a click; a template hit opens the tooltip at the click. `bodyOf` returns a marked exercise's LaTeX (by id; null for a document with one unnamed body). */
  async click(paneId: string, click: PageClick, bodyOf: (exerciseId: string | null) => string | undefined): Promise<ClickTarget | null> {
    const result = this.results.get(paneId);
    if (!result || !isClickable(result)) return null;
    const seq = this.seq;
    const word = await wordAt(result.pdfBytes, click);
    if (seq !== this.seq) return null;
    const target = resolveClick(result, click, word, bodyOf);
    this.tip = target?.kind === 'template' ? { x: click.clientX, y: click.clientY } : null;
    return target;
  }

  /** Shows what was typed on `line` (1-based, of `exerciseId`'s body) since `compiledBody` compiled, at that line's place in every pane that has it. */
  provisional(exerciseId: string | null, compiledBody: string, body: string, line: number): void {
    const before = compiledBody.split('\n');
    const now = body.split('\n');
    // Only an edit within one line maps to a place; a line added or removed waits for the PDF.
    const text = before.length === now.length ? insertedText(before[line - 1] ?? '', now[line - 1] ?? '').trim() : '';
    const next: Record<string, PageOverlay | null> = {};
    for (const [paneId, result] of this.results) {
      const range = rangeOf(result, exerciseId);
      const at = text && range ? placeOfLine(result, range, line) : null;
      next[paneId] = at ? { ...at, text } : null;
    }
    this.overlays = next;
  }
}
